    "en": "List Animal",
    "hi": "पशु सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "animalCategory",
      "type": "DROPDOWN",
      "label": {
        "en": "Animal Category",
        "hi": "पशु श्रेणी"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "animal__animal_category",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "animalName",
      "type": "DROPDOWN",
      "label": {
        "en": "Animal",
        "hi": "पशु"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 20,
      "optionSetKey": "animal__animal_name",
      "parentField": "animalCategory",
      "editableOnUpdate": false,
      "visibleWhen": {
        "field": "animalCategory",
        "operator": "notEquals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "animalNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify Animal",
        "hi": "कृपया पशु का नाम बताएं"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "animalCategory",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "animalDescription",
      "type": "TEXTAREA",
      "label": {
        "en": "Description",
        "hi": "विवरण"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "fieldLength": 1000,
      "inlineEditable": true,
      "validation": {
        "maxLength": 1000
      }
    },
    {
      "fieldKey": "breed",
      "type": "TEXT",
      "label": {
        "en": "Breed",
        "hi": "नस्ल"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 50,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      }
    },
    {
      "fieldKey": "gender",
      "type": "RADIO",
      "label": {
        "en": "Gender",
        "hi": "लिंग"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 60,
      "optionSetKey": "animal__gender"
    },
    {
      "fieldKey": "age",
      "type": "NUMBER",
      "label": {
        "en": "Age",
        "hi": "आयु"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 70,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "ageUnit",
      "type": "DROPDOWN",
      "label": {
        "en": "Age Unit",
        "hi": "आयु इकाई"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 80,
      "optionSetKey": "animal__age_unit"
    },
    {
      "fieldKey": "weight",
      "type": "DECIMAL",
      "label": {
        "en": "Weight (Kg)",
        "hi": "वजन (किग्रा)"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 90,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "purpose",
      "type": "DROPDOWN",
      "label": {
        "en": "Purpose",
        "hi": "उद्देश्य"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 100,
      "optionSetKey": "animal__purpose"
    },
    {
      "fieldKey": "healthStatus",
      "type": "CHECKBOX_GROUP",
      "label": {
        "en": "Health Status",
        "hi": "स्वास्थ्य स्थिति"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 110,
      "optionSetKey": "animal__health",
      "multiple": true
    },
    {
      "fieldKey": "availableQty",
      "type": "NUMBER",
      "label": {
        "en": "Available Quantity (no. of animals)",
        "hi": "उपलब्ध संख्या (पशुओं की संख्या)"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 120,
      "inlineEditable": true,
      "validation": {
        "min": 1
      }
    },
    {
      "fieldKey": "actualPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Actual Price (₹)",
        "hi": "वास्तविक मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 130,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "offeredPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Offered Price (₹)",
        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 140,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 150,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "(actualPrice - offeredPrice) / actualPrice * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 160,
      "common": true
    },
    {
      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 170,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "contactNumber",
      "type": "TEXT",
      "label": {
        "en": "Contact Number",
        "hi": "संपर्क नंबर"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": true,
      "displayOrder": 180,
      "common": true,
      "fieldLength": 10,
      "validation": {
        "regex": "^[6-9][0-9]{9}$",
        "maxLength": 10
      }
    },
    {
      "fieldKey": "showContact",
      "type": "BOOLEAN",
      "label": {
        "en": "Show my contact number & address to buyers",
        "hi": "मेरा संपर्क नंबर और पता खरीदारों को दिखाएं"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": false,
      "displayOrder": 190,
      "help": {
        "en": "If off, your number and full address stay hidden — buyers must send a contact request that you approve before they are revealed.",
        "hi": "यदि बंद है, तो आपका नंबर और पूरा पता छिपा रहेगा — खरीदार संपर्क अनुरोध भेजेंगे और आपकी स्वीकृति के बाद ही ये दिखेंगे।"
      },
      "common": true
    }
  ]
}

